const englishToKey = new Map(Object.entries(messages.en).map(([key, value]) => [value.toLocaleLowerCase("en"), key]));
const englishAdviceToKey = new Map(Object.entries(adviceMessages.en).map(([key, value]) => [value.toLocaleLowerCase("en"), key]));
const interfacePhraseIndex = new Map(Object.entries(interfacePhraseTranslations).map(([key, value]) => [key.toLocaleLowerCase("en"), value]));

export function message(language: Language, key: string, fallback = key): string {
  return messages[language][key] ?? messages.en[key] ?? fallback;
}

const months: Record<string, string> = {
  January: "Mutarama", February: "Gashyantare", March: "Werurwe", April: "Mata", May: "Gicurasi", June: "Kamena",
  July: "Nyakanga", August: "Kanama", September: "Nzeri", October: "Ukwakira", November: "Ugushyingo", December: "Ukuboza",
  Jan: "Mut", Feb: "Gas", Mar: "Wer", Apr: "Mat", Jun: "Kam", Jul: "Nya", Aug: "Kan", Sep: "Nze", Oct: "Ukw", Nov: "Ugu", Dec: "Uku",
  Sunday: "Ku Cyumweru", Monday: "Ku wa Mbere", Tuesday: "Ku wa Kabiri", Wednesday: "Ku wa Gatatu", Thursday: "Ku wa Kane", Friday: "Ku wa Gatanu", Saturday: "Ku wa Gatandatu",
  Sun: "Cyu", Mon: "Mbe", Tue: "Kab", Wed: "Gat", Thu: "Kan", Fri: "Gat", Sat: "Gat",
};

/** Translate existing interface/API text while components are progressively moved to t(key). */
export function translateText(value: string, language: Language): string {
  if (language === "en" || !value.trim()) return value;
  const leading = value.match(/^\s*/)?.[0] ?? "";
  const trailing = value.match(/\s*$/)?.[0] ?? "";
  const text = value.trim();
  const key = englishToKey.get(text.toLocaleLowerCase("en"));
  if (key) return `${leading}${messages.rw[key]}${trailing}`;
  const adviceKey = englishAdviceToKey.get(text.toLocaleLowerCase("en"));
  if (adviceKey) return `${leading}${adviceMessages.rw[adviceKey]}${trailing}`;
  const interfacePhrase = interfacePhraseIndex.get(text.toLocaleLowerCase("en"));
  if (interfacePhrase) return `${leading}${interfacePhrase}${trailing}`;

  const patterns: Array<[RegExp, (...parts: string[]) => string]> = [
    [/^(\d+) farms?$/i, (n) => `Imirima ${n}`], [/^(\d+) fields?$/i, (n) => `Ibice by'umurima ${n}`],
    [/^(\d+) tasks?$/i, (n) => `Imirimo ${n}`], [/^(\d+) records?$/i, (n) => `Amakuru ${n}`],
    [/^Use (.+)$/i, (name) => `Koresha ${name}`], [/^Plant (.+)$/i, (crop) => `Tera ${crop}`],
    [/^Season (.+)$/i, (season) => `Igihembwe ${season}`], [/^Mode: (.+)$/i, (mode) => `Uburyo: ${mode}`],
    [/^According to (.+)$/i, (reason) => `Hakurikijwe ${reason}`], [/^Forecast: (.+)$/i, (forecast) => `Iteganyagihe: ${forecast}`],
    [/^Next 24 hours: (.+)$/i, (forecast) => `Mu masaha 24 ari imbere: ${forecast}`],
    [/^The latest reading is (.+)\.$/i, (reading) => `Igipimo giheruka ni ${reading}.`],
    [/^Missing required measurements?: (.+)\.$/i, (items) => `Ibipimo bikenewe ntibihari: ${items}.`],
    [/^Soil moisture is (.+)\. It looks high\.$/i, (reading) => `Ubuhehere bw'ubutaka ni ${reading}. Ni bwinshi.`],
    [/^Soil moisture is (.+)\. This may be dry\.$/i, (reading) => `Ubuhehere bw'ubutaka ni ${reading}. Ubutaka bushobora kuba bwumye.`],
    [/^Soil temperature is (.+)\. This is warm for (.+)\.$/i, (reading, crop) => `Ubushyuhe bw'ubutaka ni ${reading}. Ni bwinshi ku gihingwa cya ${crop}.`],
    [/^Soil temperature is (.+)\. Heat stress risk is elevated\.$/i, (reading) => `Ubushyuhe bw'ubutaka ni ${reading}. Ibyago byo kwangizwa n'ubushyuhe byiyongereye.`],
    [/^Soil temperature is (.+)\. It is low\.$/i, (reading) => `Ubushyuhe bw'ubutaka ni ${reading}. Ni buke.`],
    [/^Soil pH is (.+), below the FAO reference range of (.+) for (.+)\.$/i, (value, range, crop) => `pH y'ubutaka ni ${value}, iri munsi y'urugero rwa FAO rwa ${range} ku gihingwa cya ${crop}.`],
    [/^Soil pH is (.+), above the FAO reference range of (.+) for (.+)\.$/i, (value, range, crop) => `pH y'ubutaka ni ${value}, iri hejuru y'urugero rwa FAO rwa ${range} ku gihingwa cya ${crop}.`],
    [/^Soil pH is (.+), within the FAO reference range of (.+) for (.+)\.$/i, (value, range, crop) => `pH y'ubutaka ni ${value}, iri mu rugero rwa FAO rwa ${range} ku gihingwa cya ${crop}.`],
    [/^Tank level is (.+); the safety minimum is (.+)\.$/i, (level, minimum) => `Amazi mu kigega ari kuri ${level}; urugero rwo hasi rw'umutekano ni ${minimum}.`],
    [/^Tank level is (.+), above the (.+) safety minimum\.$/i, (level, minimum) => `Amazi mu kigega ari kuri ${level}, hejuru y'urugero rwo hasi rw'umutekano rwa ${minimum}.`],
    [/^Soil moisture is (.+), above the (.+) (.+)\.$/i, (moisture, threshold, source) => `Ubuhehere bw'ubutaka ni ${moisture}, buri hejuru y'urugero rwa ${threshold} (${source}).`],
    [/^Soil moisture is (.+), below the (.+) (.+)\.$/i, (moisture, threshold, source) => `Ubuhehere bw'ubutaka ni ${moisture}, buri munsi y'urugero rwa ${threshold} (${source}).`],
    [/^Only (.+) mm rain is forecast in the next 24 hours \(maximum probability (.+)\)\.$/i, (rain, chance) => `Hateganyijwe imvura ya mm ${rain} gusa mu masaha 24 ari imbere (amahirwe menshi ni ${chance}).`],
    [/^The highest modelled wind speed in the next 24 hours is (.+) km\/h\.$/i, (speed) => `Umuvuduko munini w'umuyaga uteganyijwe mu masaha 24 ari imbere ni km/h ${speed}.`],
    [/^Rain is expected within the next 24 hours\.?$/i, () => "Imvura iteganyijwe mu masaha 24 ari imbere."],
    [/^No rain is expected within the next 24 hours\.?$/i, () => "Nta mvura iteganyijwe mu masaha 24 ari imbere."],
    [/^Could not load (.+)$/i, (item) => `Ntibyashobotse gutegura ${item}`],
    [/^Delete “(.+)”\?$/i, (name) => `Urashaka gusiba “${name}”?`],
    [/^Delete “(.+)” and its actual transactions\?$/i, (name) => `Urashaka gusiba “${name}” n'amafaranga nyayo ajyanye na yo?`],
    [/^Delete (.+) and all of its stored sensor readings\?$/i, (name) => `Urashaka gusiba ${name} n'ibipimo byose bya sensori byabitswe?`],
    [/^Unassign (.+) from (.+)\?$/i, (device, field) => `Urashaka gukura ${device} kuri ${field}?`],
  ];
  for (const [pattern, render] of patterns) {
    const match = text.match(pattern);
    if (match) return `${leading}${render(...match.slice(1))}${trailing}`;
  }
  let translated = text;
  for (const [english, kinyarwanda] of Object.entries(months)) translated = translated.replace(new RegExp(`\\b${english}\\b`, "g"), kinyarwanda);
  return `${leading}${translated}${trailing}`;
}

